package android.database.sqlite;
import android.content.*;import android.database.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;
/** Executes the production repository's SQL against Python's real SQLite, not an in-memory map. */
public final class SQLiteDatabase {
 public static final int CONFLICT_IGNORE=4,CONFLICT_REPLACE=5;private Process process;private BufferedWriter input;private BufferedReader output;private boolean successful;
 SQLiteDatabase(String path){try{process=new ProcessBuilder(System.getProperty("archive.python"),System.getProperty("archive.bridge"),path).redirectError(ProcessBuilder.Redirect.INHERIT).start();input=new BufferedWriter(new OutputStreamWriter(process.getOutputStream(),StandardCharsets.UTF_8));output=new BufferedReader(new InputStreamReader(process.getInputStream(),StandardCharsets.UTF_8));}catch(IOException e){throw new IllegalStateException(e);}}
 private JSONObject sql(String sql,Object... args){try{input.write(new JSONObject().put("sql",sql).put("args",new JSONArray(Arrays.asList(args))).toString());input.newLine();input.flush();String line=output.readLine();if(line==null)throw new IOException("SQLite bridge closed");JSONObject result=new JSONObject(line);if(result.has("error"))throw new IllegalStateException(result.getString("error")+" / "+sql);return result;}catch(IOException e){throw new IllegalStateException(e);}}
 public void execSQL(String text){sql(text);}public void beginTransaction(){successful=false;sql("BEGIN IMMEDIATE");}public void setTransactionSuccessful(){successful=true;}public void endTransaction(){sql(successful?"COMMIT":"ROLLBACK");}
 public long insertWithOnConflict(String table,String nullColumn,ContentValues values,int conflict){String keys=String.join(",",values.keySet()),marks=String.join(",",Collections.nCopies(values.size(),"?"));return sql("INSERT OR "+(conflict==CONFLICT_IGNORE?"IGNORE":"REPLACE")+" INTO "+table+"("+keys+") VALUES("+marks+")",values.values().toArray()).optLong("last",-1);}
 public int update(String table,ContentValues values,String where,String[] args){List<Object> all=new ArrayList<>(values.values());if(args!=null)all.addAll(Arrays.asList(args));List<String> fields=new ArrayList<>();for(String key:values.keySet())fields.add(key+"=?");return sql("UPDATE "+table+" SET "+String.join(",",fields)+(where==null?"":" WHERE "+where),all.toArray()).getInt("changes");}
 public int delete(String table,String where,String[] args){return sql("DELETE FROM "+table+(where==null?"":" WHERE "+where),args==null?new Object[0]:args).getInt("changes");}
 public Cursor query(String table,String[] columns,String where,String[] args,String group,String having,String order){return new Cursor(sql("SELECT "+(columns==null?"*":String.join(",",columns))+" FROM "+table+(where==null?"":" WHERE "+where)+(order==null?"":" ORDER BY "+order),args==null?new Object[0]:args));}
 public void close(){try{input.close();process.waitFor();}catch(Exception e){throw new IllegalStateException(e);}}
}
